#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  $exe=".exe"
}
$ret=0
if (Test-Path "$basedir/node$exe") {
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../.deno/@electric-sql+pglite-socket@0.0.6/node_modules/@electric-sql/pglite-socket/dist/scripts/server.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../.deno/@electric-sql+pglite-socket@0.0.6/node_modules/@electric-sql/pglite-socket/dist/scripts/server.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../.deno/@electric-sql+pglite-socket@0.0.6/node_modules/@electric-sql/pglite-socket/dist/scripts/server.js" $args
  } else {
    & "node$exe"  "$basedir/../.deno/@electric-sql+pglite-socket@0.0.6/node_modules/@electric-sql/pglite-socket/dist/scripts/server.js" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
